# The paper's figures in Julia (src/figures.jl, module Figures): the colour coding is the Python figures' (flowcolor.py, a 16 × 16
# field generated by test/fixtures/figures/wheel_reference.py), the field interpolation is linear on the Delaunay triangulation, and
# every figure function renders from a small record to a PNG of the
# expected size.
@testitem "figures" default_imports = false begin
    using Test
    using DrWatson
    import PNGFiles
    import VisualGeometryToolkitIO as VgtkIO
    import VisualGeometryToolkitCore as VgtkCore
    using StaticArrays: SVector
    using ColorTypes: RGB, N0f16
    include(srcdir("record_schemas.jl"))
    include(srcdir("figures.jl"))
    using .Figures

    png_size(path) = (img = PNGFiles.load(path); (size(img, 2), size(img, 1)))       # (width, height)

    @testset "the colour wheel is the Python one (flowcolor.py)" begin
        ref = VgtkIO.read_record(projectdir("test", "fixtures", "figures", "flowcolor_reference.json"))
        vmax = Float64(ref.vmax); worst = 0.0; same8 = true
        for i in 1:16, j in 1:16
            rgb = flow_rgb(Float64(ref.dx[i][j]), Float64(ref.dy[i][j]), vmax)
            py = Float64.(ref.rgb[i][j])
            worst = max(worst, maximum(abs.(collect(rgb) .- py)))
            same8 &= round.(Int, 255 .* collect(rgb)) == round.(Int, 255 .* py)
        end
        @test worst <= 1e-12            # stated tolerance: the same float operations as matplotlib's hsv_to_rgb, so ≤ a few ulp
        @test same8                     # the 8-bit pixels of the figures are identical
    end

    @testset "the field linear on the Delaunay triangulation" begin
        x = [10.0, 390, 10, 390, 200, 120, 300]; y = [10.0, 10, 290, 290, 150, 60, 220]
        f(x, y) = 0.01x - 0.02y + 1                     # a linear field is reproduced exactly inside the hull
        ux, uy, ok = dense_points(x, y, f.(x, y), -f.(x, y), 400, 300, 8)
        @test count(ok) > 0.8 * length(ok)
        @test maximum(abs(ux[r, c] - f((c - 0.5) * 8, (r - 0.5) * 8)) for r in axes(ux, 1), c in axes(ux, 2) if ok[r, c]) < 1e-9
        @test !ok[1, 1]                                  # outside the hull: blank
        _, _, ok2 = dense_points([1.0, 2], [1.0, 2], [0.0, 0], [0.0, 0], 400, 300, 8)     # fewer than three nodes: nothing
        @test !any(ok2)
    end

    @testset "the arrow figure's cells: the measurement nearest each cell's centre (thin_vectors)" begin
        x = [10.0, 24.0, 26.0, 70.0, 75.0, 500.0]; y = [10.0, 26.0, 24.0, 10.0, 30.0, 10.0]
        tx, ty, tdx, tdy = thin_vectors(x, y, collect(1.0:6), zeros(6), 0.0, 0.0, 50.0, 2, 2)
        @test tdx == [2.0, 5.0]                     # cell (0,0): (24, 26) nearest (25, 25), the first of a tie; cell (1,0): (75, 30); 500 outside
        @test tx == [24.0, 75.0] && ty == [26.0, 30.0]
    end

    @testset "the count grid: points per cell, rows = y (grid_counts)" begin
        # a 300 × 200 image in a 3 × 2 grid: cells 100 × 100 px; a point on a border belongs to the cell right / below it
        x = [10.0, 99.9, 100.0, 250.0, 299.0, 50.0, 300.0, -1.0, NaN, 150.0]
        y = [10.0, 10.0, 10.0, 150.0, 199.9, 100.0, 50.0, 50.0, 10.0, 200.0]
        @test grid_counts(x, y, 300, 200, 3, 2) == [2 1 0; 1 0 2]   # 300 / -1 / NaN / y = 200 outside
        @test sum(grid_counts(rand(500) .* 4256, rand(500) .* 2848, 4256, 2848, 9, 6)) == 500
    end

    @testset "the figures render from fixture runs (into a scratch directory, never plots/)" begin
        dir = mktempdir()
        plots_before = isdir(plotsdir()) ? Set(readdir(plotsdir())) : Set{String}()
        # the arrow style of fig:color-wheels: one row per pair of panels, the three views
        xs = [Float64(x) for x in 20:40:380 for _ in 20:40:280]; ys = [Float64(y) for _ in 20:40:380 for y in 20:40:280]
        vec = joinpath(dir, "vectors.json"); VgtkIO.write_record(vec, (; schema = EXPERIMENT_RECORD_SCHEMAS.residual_vectors, x = xs, y = ys, dx = 0.01 .* (xs .- 200), dy = -0.01 .* (ys .- 150)))
        pan(v) = [("start", "scatter", vec, 0.5), ("refined", "scatter", vec, 0.5)]
        r = Dict{String,Any}("asset" => "test_arrows.png", "title" => "", "size" => [400, 300], "cols" => 2, "dpi" => 50, "style" => "arrows",
                             "cells_x" => 8, "len_cells_x" => 8,
                             "panels" => [Dict("view" => v) for v in ("sensor", "sensor", "overflow", "overflow", "zoom", "zoom")])
        p = figure_wheel_map(vcat(pan("sensor"), pan("overflow"), pan("zoom")); render = r, dir)
        @test png_size(p) == (round(Int, (5.2 * 2 + 0.15) * 50), round(Int, 3.75 * 3 * 50)); rm(p); rm(vec)
        @test all(startswith(dir), [p]) && isempty(readdir(dir))
        @test (isdir(plotsdir()) ? Set(readdir(plotsdir())) : Set{String}()) == plots_before
    end

end
